71	@RestController
72	@CrossOrigin(exposedHeaders = "errors, content-type")
73	@RequestMapping("/api")
74	public class OwnerRestControllerV1 implements OwnersApi {
75	
76	    /**
77	     * Syntactic email check: a non-empty local part, a single {@code @}, and a domain that
78	     * contains at least one dot, with no whitespace anywhere. Deliberately lenient — it accepts
79	     * ordinary addresses while rejecting clearly malformed ones such as {@code not-an-email}.
80	     */
81	    private static final Pattern EMAIL_PATTERN =
82	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
83	
84	    /**
85	     * Disposable email domains that are refused on create. An email whose domain (the part after the
86	     * {@code @}, compared case-insensitively) is in this set is rejected with a 400, since such
87	     * addresses are throwaway and unsuitable for contacting an owner.
88	     */
89	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS =
90	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
91	
92	    /**
93	     * Dedicated audit logger. On a successful create an audit line carrying the owner id, the
94	     * customerCode, the registrationDate and the membershipLevel is emitted through this logger.
95	     */
96	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
97	
98	    /**
99	     * Remembers the owner created for each {@code Idempotency-Key} seen on a create, so a repeated
100	     * create carrying a key already in this map returns the originally created owner (200) instead of
101	     * creating a duplicate. Keys are supplied by the caller and are process-wide.
102	     */
103	    private final java.util.Map<String, Integer> idempotencyKeys = new java.util.concurrent.ConcurrentHashMap<>();
104	
105	    private final ClinicService clinicService;
106	
107	    private final OwnerMapper ownerMapper;
108	
109	    private final PetMapper petMapper;
110	
111	    private final VisitMapper visitMapper;
112	
113	    public OwnerRestControllerV1(ClinicService clinicService,
114	                                 OwnerMapper ownerMapper,
115	                                 PetMapper petMapper,
116	                                 VisitMapper visitMapper) {
117	        this.clinicService = clinicService;
118	        this.ownerMapper = ownerMapper;
119	        this.petMapper = petMapper;
120	        this.visitMapper = visitMapper;
121	    }
122	
123	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
124	    @Override
125	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
126	        Collection<Owner> owners;
127	        if (lastName != null) {
128	            owners = this.clinicService.findOwnerByLastName(lastName);
129	        } else {
130	            owners = this.clinicService.findAllOwners();
131	        }
132	        if (owners.isEmpty()) {
133	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
134	        }
135	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
136	    }
137	
138	    /**
139	     * Rejects an owner payload that is missing or blank in any required field, listing the name of
140	     * each offending field so the caller receives a 400 with a populated {@code errors} array.
141	     */
142	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
143	        List<String> missing = new ArrayList<>();
144	        if (isBlank(ownerFieldsDto.getFirstName())) {
145	            missing.add("firstName");
146	        }
147	        if (isBlank(ownerFieldsDto.getLastName())) {
148	            missing.add("lastName");
149	        }
150	        if (isBlank(ownerFieldsDto.getAddress())) {
151	            missing.add("address");
152	        }
153	        if (isBlank(ownerFieldsDto.getCity())) {
154	            missing.add("city");
155	        }
156	        if (isBlank(ownerFieldsDto.getTelephone())) {
157	            missing.add("telephone");
158	        }
159	        if (!missing.isEmpty()) {
160	            throw new RequiredFieldsMissingException(missing);
161	        }
162	    }
163	
164	    private static boolean isBlank(String value) {
165	        return value == null || value.isBlank();
166	    }
167	
168	    /**
169	     * Normalizes an address on create: leading/trailing whitespace is trimmed, every run of internal
170	     * whitespace is collapsed to a single space, the value is upper-cased and common abbreviations are
171	     * expanded token-by-token ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). The
172	     * normalized value is what gets stored, returned and used for every address comparison; a value
173	     * that is blank (or {@code null}) normalizes to the empty string so the required-field check
174	     * rejects it.
175	     *
176	     * @param address the raw address as supplied by the caller, may be {@code null}
177	     * @return the normalized address ({@code ""} when blank or {@code null})
178	     */
179	    private static String normalizeAddress(String address) {
180	        if (address == null) {
181	            return "";
182	        }
183	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
184	        if (collapsed.isEmpty()) {
185	            return "";
186	        }
187	        String[] tokens = collapsed.split(" ");
188	        StringBuilder sb = new StringBuilder(collapsed.length());
189	        for (int i = 0; i < tokens.length; i++) {
190	            String token = tokens[i];
191	            switch (token) {
192	                case "ST" -> token = "STREET";
193	                case "RD" -> token = "ROAD";
194	                case "AVE" -> token = "AVENUE";
195	                default -> { }
196	            }
197	            if (i > 0) {
198	                sb.append(' ');
199	            }
200	            sb.append(token);
201	        }
202	        return sb.toString();
203	    }
204	
205	    /**
206	     * Resolves and normalizes the owner's address on create, supporting both the structured form
207	     * ({@code addressLine1} / {@code addressLine2}) and the flat {@code address} form kept for
208	     * backward compatibility. Whichever address fields are supplied are normalized (see
209	     * {@link #normalizeAddress(String)}). The structured form is preferred when present: when
210	     * {@code addressLine1} is non-blank the composed {@code address} is the normalized
211	     * {@code addressLine1}, with a single space and the normalized {@code addressLine2} appended when
212	     * {@code addressLine2} is present; otherwise the composed {@code address} is the normalized flat
213	     * {@code address}. The normalized structured fields are written back so they are stored and
214	     * returned, and the composed value is written to {@code address} so everything that reads the
215	     * address (the household hash, postcode validation and locality) uses the structured fields when
216	     * present, falling back to the flat address. When neither form supplies an address the composed
217	     * {@code address} is blank, so the required-field check rejects it.
218	     *
219	     * @param ownerFieldsDto the owner payload whose address fields are normalized in place
220	     */
221	    private static void applyAddress(OwnerFieldsDto ownerFieldsDto) {
222	        String line1 = normalizeAddress(ownerFieldsDto.getAddressLine1());
223	        String line2 = normalizeAddress(ownerFieldsDto.getAddressLine2());
224	        String flat = normalizeAddress(ownerFieldsDto.getAddress());
225	        String composed;
226	        if (!line1.isEmpty()) {
227	            composed = line2.isEmpty() ? line1 : line1 + " " + line2;
228	        } else {
229	            composed = flat;
230	        }
231	        ownerFieldsDto.setAddressLine1(line1.isEmpty() ? null : line1);
232	        ownerFieldsDto.setAddressLine2(line2.isEmpty() ? null : line2);
233	        ownerFieldsDto.setAddress(composed);
234	    }
235	
236	    /**
237	     * Normalizes a telephone on create into E.164 form. Spaces, dashes and brackets are stripped.
238	     * A leading {@code +} and its country code are kept as given; otherwise the country code
239	     * {@code +61} is assumed and a single leading {@code 0} is dropped from the national digits.
240	     * The result must carry 8 to 15 digits after the {@code +}. In addition, when the country code
241	     * is recognized the national number must have the exact length that code requires ({@code +61}
242	     * expects 9 national digits, {@code +1} expects 10). Returns the E.164 string to be stored and
243	     * returned.
244	     *
245	     * @param telephone the raw telephone as supplied by the caller
246	     * @return the normalized E.164 telephone (a {@code +} followed by 8 to 15 digits)
247	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number, or its
248	     *     national-number length is wrong for its country code
249	     */
250	    private static String normalizeTelephone(String telephone) {
251	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
252	        String e164;
253	        if (cleaned.startsWith("+")) {
254	            e164 = "+" + cleaned.substring(1);
255	        } else {
256	            String national = cleaned;
257	            if (national.startsWith("0")) {
258	                national = national.substring(1);
259	            }
260	            e164 = "+61" + national;
261	        }
262	        String digits = e164.substring(1);
263	        if (!digits.matches("\\d{8,15}")) {
264	            throw new InvalidTelephoneException(
265	                "Telephone must form a valid E.164 number with 8 to 15 digits after the '+'");
266	        }
267	        if (digits.startsWith("61")) {
268	            requireNationalLength(digits.substring(2), 9, "+61");
269	        } else if (digits.startsWith("1")) {
270	            requireNationalLength(digits.substring(1), 10, "+1");
271	        }
272	        return e164;
273	    }
274	
275	    /**
276	     * Enforces that the national portion of an E.164 number has the exact number of digits its
277	     * country code requires.
278	     *
279	     * @param national the national-number digits (the part after the country code)
280	     * @param expected the exact national-number length the country code requires
281	     * @param countryCode the country code, for the error message
282	     * @throws InvalidTelephoneException if {@code national} does not have exactly {@code expected} digits
283	     */
284	    private static void requireNationalLength(String national, int expected, String countryCode) {
285	        if (national.length() != expected) {
286	            throw new InvalidTelephoneException(
287	                "Telephone with country code '" + countryCode + "' must have " + expected
288	                    + " national digits");
