366	    /**
367	     * Rejects a create when an existing owner already belongs to the same household (i.e. carries the
368	     * same computed {@code householdId}, derived from last name and postcode), unless the request
369	     * knowingly opts in via {@code sharesHousehold}. Setting {@code sharesHousehold} bypasses this
370	     * block so the owner is created as a declared member of the existing household; without it, a
371	     * second owner in the same household is a conflict.
372	     *
373	     * @param householdId the computed household identifier of the owner being created
374	     * @param sharesHousehold whether the request opted in to sharing an existing household
375	     * @throws DuplicateHouseholdException if the household already exists and the request did not opt in
376	     */
377	    private void rejectDuplicateHousehold(String householdId, boolean sharesHousehold) {
378	        if (sharesHousehold) {
379	            return;
380	        }
381	        boolean exists = activeOwners()
382	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
383	        if (exists) {
384	            throw new DuplicateHouseholdException(
385	                "An owner with the same last name and postcode already exists");
386	        }
387	    }
