416	    /**
417	     * Derives the stable household identifier for an owner from its last name and postcode. The value
418	     * is the first twelve hex characters of the SHA-256 of {@code normalizedLastName + '|' + postcode}
419	     * (the last name normalized case-insensitively with surrounding whitespace trimmed; an absent
420	     * postcode contributes the empty string). Because it is a pure function of those two fields, every
421	     * owner with the same last name and postcode is assigned the same identifier automatically, without
422	     * any existing record having to be updated.
423	     *
424	     * @param lastName the last name of the owner being created
425	     * @param postcode the postcode of the owner being created, may be {@code null}
426	     * @return the stable household identifier
427	     */
428	    private static String householdId(String lastName, String postcode) {
429	        String key = normalizeName(lastName) + "|" + (postcode == null ? "" : postcode);
430	        return sha256HexPrefix(key, 12);
431	    }
