492	    /**
493	     * Determines whether a create should be flagged with a bulk-signup warning, i.e. whether more than
494	     * {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been created for the given business day,
495	     * counted by {@code registrationDate} equal to the effective (weekend rolled forward) registration
496	     * date of the owner being created. The count reflects the state before the new owner is persisted,
497	     * so it excludes the owner being created.
498	     *
499	     * @param registrationDate the effective business-day registration date of the owner being created
500	     * @return {@code true} when more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry the date
501	     */
502	    private boolean bulkSignupWarning(LocalDate registrationDate) {
