532	    /**
533	     * Builds the customer code assigned to an owner on create, formatted {@code '<REGION>-<HASH8>'}
534	     * where {@code REGION} is the region code derived from the owner's postcode (the region whose
535	     * inclusive range contains the postcode, or {@code 'UNKNOWN'} when the postcode is absent or in
536	     * no known range) and {@code HASH8} is the first eight upper-cased hex characters of the SHA-256
537	     * of {@code normalizedTelephone + lastName}, e.g. {@code 'NSW-1A2B3C4D'}. There is no sequence
538	     * component: the identity is a pure region-and-hash value.
539	     *
540	     * @param postcode the postcode of the owner being created, may be {@code null}
541	     * @param normalizedTelephone the E.164 telephone of the owner being created
542	     * @param lastName the last name of the owner being created
543	     * @return the formatted customer code
544	     */
545	    private String customerCode(String postcode, String normalizedTelephone, String lastName) {
546	        return regionFromPostcode(postcode) + "-" + sha256HexPrefix(normalizedTelephone + lastName, 8);
547	    }
548	
549	    /**
550	     * De-duplicates a freshly computed customer code against the customer codes already held by
551	     * existing owners. When the code is unused it is returned unchanged; otherwise {@code '-<n>'} is
552	     * appended with the smallest {@code n} of 2 or more that yields a code no existing owner carries.
553	     *
554	     * @param customerCode the computed customer code for the owner being created
555	     * @return the same code when unique, otherwise the code with a {@code '-<n>'} suffix that makes
556	     *     it unique
557	     */
558	    private String deduplicateCustomerCode(String customerCode) {
559	        Set<String> existing = new java.util.HashSet<>();
560	        for (Owner owner : this.clinicService.findAllOwners()) {
561	            if (owner.getCustomerCode() != null) {
562	                existing.add(owner.getCustomerCode());
563	            }
564	        }
565	        if (!existing.contains(customerCode)) {
566	            return customerCode;
567	        }
568	        int n = 2;
569	        while (existing.contains(customerCode + "-" + n)) {
570	            n++;
571	        }
572	        return customerCode + "-" + n;
573	    }
