575	    /**
576	     * Returns the region code whose inclusive postcode range contains the given 4-digit postcode
577	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), or {@code 'UNKNOWN'} when the postcode is
578	     * {@code null}, non-numeric, or in no known range.
579	     *
580	     * @param postcode the postcode, may be {@code null}
581	     * @return the region code, or {@code 'UNKNOWN'}
582	     */
583	    private static String regionFromPostcode(String postcode) {
584	        if (postcode == null || postcode.isBlank()) {
585	            return "UNKNOWN";
586	        }
587	        int code;
588	        try {
589	            code = Integer.parseInt(postcode.trim());
590	        } catch (NumberFormatException e) {
591	            return "UNKNOWN";
592	        }
593	        for (java.util.Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
594	            int[] range = entry.getValue();
595	            if (code >= range[0] && code <= range[1]) {
596	                return entry.getKey();
597	            }
598	        }
599	        return "UNKNOWN";
600	    }
