602	    /**
603	     * Computes the SHA-256 of {@code value} and returns its first {@code length} hex characters,
604	     * upper-cased.
605	     *
606	     * @param value the string to hash
607	     * @param length the number of leading hex characters to return
608	     * @return the upper-cased hex prefix of the digest
609	     */
610	    private static String sha256HexPrefix(String value, int length) {
611	        try {
612	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
613	            StringBuilder sb = new StringBuilder(digest.length * 2);
614	            for (byte b : digest) {
615	                sb.append(String.format("%02x", b));
616	            }
617	            return sb.substring(0, length).toUpperCase(Locale.ROOT);
618	        } catch (NoSuchAlgorithmException e) {
619	            throw new IllegalStateException("SHA-256 not available", e);
620	        }
621	    }
