623	    /**
624	     * Counts the existing owners that share the owner-to-be's first and last name, compared
625	     * case-insensitively (surrounding whitespace trimmed). The count reflects the state before the
626	     * new owner is persisted, so it excludes the owner being created.
627	     *
628	     * @param firstName the first name of the owner being created
629	     * @param lastName the last name of the owner being created
630	     * @return the number of existing owners with the same first and last name
631	     */
632	    private int countNamesakes(String firstName, String lastName) {
633	        String normalizedFirstName = normalizeName(firstName);
634	        String normalizedLastName = normalizeName(lastName);
635	        return (int) this.clinicService.findAllOwners().stream()
636	            .filter(existing ->
637	                normalizedFirstName.equals(normalizeName(existing.getFirstName()))
638	                    && normalizedLastName.equals(normalizeName(existing.getLastName())))
639	            .count();
640	    }
