642	    /**
643	     * Counts the members of the owner-to-be's household after this create, i.e. one more than the
644	     * number of existing owners already carrying the same {@code householdId}. The household
645	     * identifier is a deterministic function of last name and postcode, so a solo owner (the only one
646	     * with that identifier) is a household of one. The count includes the owner being created (hence
647	     * the {@code + 1}).
648	     *
649	     * @param householdId the stable household identifier of the owner being created
650	     * @return the number of household members after this create (always at least 1)
651	     */
652	    private int householdSize(String householdId) {
653	        if (householdId == null) {
654	            return 1;
655	        }
656	        return (int) this.clinicService.findAllOwners().stream()
657	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
