661	    /**
662	     * Normalizes a name for case-insensitive comparison by trimming surrounding whitespace and
663	     * lower-casing.
664	     *
665	     * @param value the raw name, may be {@code null}
666	     * @return the normalized name ({@code ""} when {@code value} is {@code null})
667	     */
668	    private static String normalizeName(String value) {
669	        return value == null ? "" : value.trim().toLowerCase(Locale.ROOT);
