672	    /**
673	     * The fixed city-to-region table used to validate a postcode against its city
674	     * (Sydney->NSW, Melbourne->VIC, Brisbane->QLD). A city not in this table has no known region and
675	     * therefore accepts any 4-digit postcode.
676	     */
677	    private static final java.util.Map<String, String> CITY_REGION = java.util.Map.of(
678	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
679	
680	    /**
681	     * The fixed region-to-postcode-range table: each region admits an inclusive 4-digit range
682	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099).
683	     */
684	    private static final java.util.Map<String, int[]> REGION_POSTCODES = java.util.Map.of(
685	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
686	
687	    /**
688	     * Validates an owner's optional postcode on create. A {@code null} or blank postcode is left
689	     * untouched (postcode is optional when absent). When present it must be exactly four digits and,
690	     * when the city maps to a known region, must fall within that region's inclusive range
691	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit
692	     * postcode.
693	     *
694	     * @param city the city of the owner being created
695	     * @param postcode the raw postcode as supplied by the caller, may be {@code null}
696	     * @throws InvalidPostcodeException if a present postcode is not four digits or is out of range
697	     *     for the city's region
698	     */
699	    private static void validatePostcode(String city, String postcode) {
700	        if (postcode == null || postcode.isBlank()) {
701	            return;
702	        }
703	        if (!postcode.matches("\\d{4}")) {
704	            throw new InvalidPostcodeException("Postcode must be exactly 4 digits");
705	        }
706	        String region = CITY_REGION.get(city);
707	        int[] range = region == null ? null : REGION_POSTCODES.get(region);
708	        if (range != null) {
709	            int value = Integer.parseInt(postcode);
710	            if (value < range[0] || value > range[1]) {
711	                throw new InvalidPostcodeException(
712	                    "Postcode is out of range for the city's region");
713	            }
714	        }
715	    }
