743	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
744	    @Override
745	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
746	        String idempotencyKey = currentIdempotencyKey();
747	        if (idempotencyKey != null) {
748	            Integer existingId = idempotencyKeys.get(idempotencyKey);
749	            if (existingId != null) {
750	                Owner existing = this.clinicService.findOwnerById(existingId);
751	                if (existing != null) {
752	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), HttpStatus.OK);
753	                }
754	            }
755	        }
756	        applyAddress(ownerFieldsDto);
757	        validateRequiredFields(ownerFieldsDto);
758	        LocalDate registrationDate = ownerFieldsDto.getRegistrationDate();
759	        if (registrationDate == null) {
760	            registrationDate = LocalDate.now();
761	        } else if (registrationDate.isAfter(LocalDate.now())) {
762	            throw new FutureRegistrationDateException(
763	                "registrationDate must not be later than the server date");
764	        }
765	        registrationDate = toBusinessDay(registrationDate);
766	        ownerFieldsDto.setRegistrationDate(registrationDate);
767	        rejectDailyOwnerLimit(registrationDate);
768	        rejectCityAtCapacity(ownerFieldsDto.getCity());
769	        validatePostcode(ownerFieldsDto.getCity(), ownerFieldsDto.getPostcode());
770	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
771	        ownerFieldsDto.setTelephone(normalizedTelephone);
772	        String normalizedEmail = normalizeEmail(ownerFieldsDto.getEmail());
773	        ownerFieldsDto.setEmail(normalizedEmail);
774	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
775	        String ownerHouseholdId = householdId(ownerFieldsDto.getLastName(), ownerFieldsDto.getPostcode());
776	        rejectDuplicateIdentity(deriveIdentityKey(normalizedTelephone, normalizedEmail, ownerHouseholdId));
777	        rejectDuplicateHousehold(ownerHouseholdId, sharesHousehold);
778	        Integer possibleDuplicateOf = sharesHousehold ? null : findPossibleDuplicateOf(
779	            ownerFieldsDto.getLastName(), ownerFieldsDto.getPostcode(), normalizedTelephone);
780	        HttpHeaders headers = new HttpHeaders();
781	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
782	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
783	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
784	        owner.setCustomerCode(deduplicateCustomerCode(customerCode(
785	            ownerFieldsDto.getPostcode(), normalizedTelephone, ownerFieldsDto.getLastName())));
786	        owner.setHouseholdId(ownerHouseholdId);
787	        owner.setHouseholdSize(householdSize(ownerHouseholdId));
788	        owner.setNamesakeCount(countNamesakes(ownerFieldsDto.getFirstName(), ownerFieldsDto.getLastName()));
789	        owner.setBulkSignupWarning(bulkSignupWarning(registrationDate));
790	        this.clinicService.saveOwner(owner);
791	        if (idempotencyKey != null) {
792	            idempotencyKeys.put(idempotencyKey, owner.getId());
793	        }
794	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
